function validate([l, r, b]) {
  const plain = /^(0|[1-9][0-9]*)$/;
  if (typeof l !== 'string' || typeof r !== 'string' || !plain.test(l) || !plain.test(r)) return 'l and r must be digit strings without leading zeros.';
  if (l.length > 100 || r.length > 100) return 'l and r have at most 100 digits.';
  if (l.length > r.length || (l.length === r.length && l > r)) return 'l must not be greater than r.';
  if (!Number.isInteger(b) || b < 2 || b > 10) return 'b is an integer from 2 to 10.';
  return null;
}

