function countNumbers(l, r, b) {
  const low = BigInt(l), high = BigInt(r);
  const nonDecreasing = (value) => {
    const text = value.toString(b);
    for (let i = 1; i < text.length; i++) if (text[i] < text[i - 1]) return false;
    return true;
  };
  let count = 0;
  if (high - low <= 50000n) {
    // A narrow range: test every number in it.
    for (let value = low; value <= high; value++) if (nonDecreasing(value)) count++;
    return count % 1000000007;
  }
  // A wide range: list every number whose base-b digits never decrease (no longer than r) and keep those in [l, r].
  const base = BigInt(b);
  if (low === 0n) count++;
  const extend = (value, last) => {
    if (value > high) return;
    if (value >= low) count++;
    for (let digit = last; digit < b; digit++) extend(value * base + BigInt(digit), digit);
  };
  for (let first = 1; first < b; first++) extend(BigInt(first), first);
  return count % 1000000007;
}

