function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const number = (length) => {
    let text = String(int(1, 9));
    while (text.length < length) text += String(int(0, 9));
    return text;
  };
  const ordered = (x, y) => (BigInt(x) <= BigInt(y) ? [x, y] : [y, x]);
  const b = int(2, 10);
  if (size === 'large') {
    const kind = rand();
    if (kind < 0.4) return [String(int(1, 1000)), number(int(90, 100)), b];
    const [l, r] = ordered(number(int(1, 100)), number(int(60, 100)));
    return [l, r, b];
  }
  const kind = rand();
  if (kind < 0.45) {
    // Small numbers: every number in the range can be checked.
    const [l, r] = ordered(String(int(rand() < 0.08 ? 0 : 1, 3000)), String(int(1, 3000)));
    return [l, r, b];
  }
  if (kind < 0.75) {
    // Huge numbers in a short range.
    const l = number(int(15, 100));
    return [l, (BigInt(l) + BigInt(int(0, 300))).toString(), b];
  }
  // A wide range in base 2 or 3, where few numbers have non-decreasing digits.
  return [String(int(1, 50)), number(int(10, 100)), int(2, 3)];
}
